import type { EngineInterface, On, PluginOptions } from 'claude-code';
import { agentKey, usedCodeIntelThisTurn } from './budget';
import { searchTarget } from './classify';
import { codeIntel, isConfigured, projectRoot, withinDeadline } from './lib';
import { PROMPT } from './theme';

/**
 * How long a finished search waits for its code_intel lookup before it returns
 * the search result alone. The lookup starts with the search, so it has the
 * search's own time as well. Allows for a cold start of the MCP server.
 */
export const SOFT_DEADLINE_MS = 2500;

/** How long a lookup that failed (server down, sign-in, timeout) is remembered before it is tried again. */
export const FAILURE_BACKOFF_MS = 60_000;

/** What the lookup reports for an exact-name symbol match. */
export type Found = {
	name: string;
	kind: string;
	filePath: string;
	line: number;
	/** The graph's usage count of the symbol. */
	usages: number;
	/** How many symbols carry the name; the one reported is the most used. */
	definitions: number;
};

/**
 * Lookups by project root and identifier: in flight, or settled to a match,
 * null (no exact match) or undefined (failed). A failure is dropped after
 * `FAILURE_BACKOFF_MS`, so a down server costs one lookup a minute, not one per search.
 */
const lookups = new Map<string, Promise<Found | null | undefined>>();

/**
 * Lines already shown, by agent, project root and identifier. Claimed before the
 * lookup is awaited, so parallel searches show one line, and released when no
 * line is shown.
 */
const shown = new Set<string>();

/** The part of code_intel's `api` the lookup uses. */
export type LookupApi = {
	searchSymbols: (params: {
		query: string;
		limit: number;
		includeUsageCount: boolean;
		isExported?: boolean;
	}) => Promise<{ symbols: ReadonlyArray<{ name: string; kind: string; filePath: string; line: number; usageCount?: number }> }>;
};

/**
 * The most used exact-name match for `name`, searched among exported symbols
 * first, then among used symbols that are not exported (an unused one there is
 * usually a fixture, not what the search means), or null when nothing matches.
 * `searchSymbols` matches substrings, so the exact name can sit far down a
 * page; a full page is read.
 *
 * Runs inside code_intel: `lookupCode` sends its source, so it may use only
 * its arguments.
 */
export async function lookupSymbol(api: LookupApi, name: string): Promise<Found | null> {
	const exact = async (isExported?: boolean) =>
		(await api.searchSymbols({ query: name, limit: 100, includeUsageCount: true, ...(isExported ? { isExported } : {}) })).symbols.filter(
			(s) => s.name === name,
		);
	let hits = await exact(true);
	if (hits.length === 0) hits = (await exact()).filter((s) => (s.usageCount ?? 0) > 0);
	const hit = hits.reduce<(typeof hits)[number] | null>((a, b) => (a === null || (b.usageCount ?? 0) > (a.usageCount ?? 0) ? b : a), null);
	if (hit === null) return null;
	return { name: hit.name, kind: hit.kind, filePath: hit.filePath, line: hit.line, usages: hit.usageCount ?? 0, definitions: hits.length };
}

/** The code_intel program that runs `lookupSymbol` for `name`. */
export function lookupCode(name: string): string {
	return `return await (${lookupSymbol.toString()})(api, ${JSON.stringify(name)});`;
}

/** The lookup's result read into `Found`, or null when it is not one. */
function foundOf(value: unknown): Found | null {
	if (typeof value !== 'object' || value === null) return null;
	const name: unknown = Reflect.get(value, 'name');
	const kind: unknown = Reflect.get(value, 'kind');
	const filePath: unknown = Reflect.get(value, 'filePath');
	const line: unknown = Reflect.get(value, 'line');
	const usages: unknown = Reflect.get(value, 'usages');
	const definitions: unknown = Reflect.get(value, 'definitions');
	if (typeof name !== 'string' || typeof kind !== 'string' || typeof filePath !== 'string') return null;
	if (typeof line !== 'number' || typeof usages !== 'number' || typeof definitions !== 'number') return null;
	return { name, kind, filePath, line, usages, definitions };
}

/** The one line a search result gains. */
export function augmentLine({ name, kind, filePath, line, usages, definitions }: Found): string {
	const others = definitions > 1 ? `, the most used of ${definitions} symbols with that name` : '';
	const count = `${usages} ${usages === 1 ? 'usage' : 'usages'}`;
	return `${PROMPT} ${name} (${kind}) is defined at ${filePath}:${line}${others}, with ${count}. Use code_intel for references, callers, and impact.`;
}

/** The lookup for `name` in the project at `root`, shared with any already in flight or settled. */
function lookup($: EngineInterface, root: string, name: string): Promise<Found | null | undefined> {
	const key = `${root}\0${name}`;
	let pending = lookups.get(key);
	if (pending === undefined) {
		const started: Promise<Found | null | undefined> = codeIntel(
			{ connect: (s) => $.mcp.connect(s), call: (s, t, a) => $.mcp.call(s, t, a) },
			lookupCode(name),
			{ cwd: root },
		).then((envelope) => {
			if (envelope.success) return foundOf(envelope.result);
			// Only this failure is dropped: after a reset a newer lookup may hold the key.
			$.clock.after(FAILURE_BACKOFF_MS, () => {
				if (lookups.get(key) === started) lookups.delete(key);
			});
			return undefined;
		});
		lookups.set(key, started);
		pending = started;
	}
	return pending;
}

export function registerAugment(on: On, options: PluginOptions): void {
	lookups.clear();
	shown.clear();
	if (options.augmentGrep === false) return;

	on('tool.call', { tool: /^(Grep|Bash)$/ }, async ($, e, next) => {
		if (!isConfigured(await $.env.get('CONSTELLATION_ACCESS_KEY'))) return next(e);
		const { symbol, path } = searchTarget(e);
		if (symbol === null || usedCodeIntelThisTurn(e)) return next(e);
		const root = await projectRoot(await $.session.cwd(), (p) => $.fs.exists(p), path);
		if (root === null) return next(e);
		const seen = `${agentKey(e)}\0${root}\0${symbol}`;
		if (shown.has(seen)) return next(e);

		shown.add(seen);
		const pending = lookup($, root, symbol);
		const r = await next(e);
		if (r.deny !== undefined || r.isError) {
			shown.delete(seen);
			return r;
		}
		const found = await withinDeadline((ms, o) => $.clock.sleep(ms, o), pending, SOFT_DEADLINE_MS, next.signal);
		if (found === null || found === undefined) {
			shown.delete(seen);
			return r;
		}
		return { ...r, context: [...(r.context ?? []), augmentLine(found)] };
	});
}

/** Forgets every lookup and shown line, for a new conversation (`/clear`, `/resume`, `/branch`). */
export function resetAugment(): void {
	lookups.clear();
	shown.clear();
}

/** Forgets the lines shown to the subagent `agentId` when its run ends; lookups stay shared. */
export function forgetAgentLines(agentId: string): void {
	const prefix = `${agentId}\0`;
	for (const key of shown) if (key.startsWith(prefix)) shown.delete(key);
}

files.hooks/budget.ts:
import type { On, PluginOptions } from 'claude-code';
import { background, noteCodeIntelCall, save, showsAdoption } from './adoption';
import { observeEnvelope } from './freshness';
import { absolute, canDraw, isConfigured, parseToolText, projectRoot, stringArg } from './lib';
import { observeCodeIntel } from './onboarding';
import { noteCodeIntel } from './risk';

/** How many nudges one agent gets when the option is unset. */
const DEFAULT_NUDGE_LIMIT = 3;

/** The agent key of the main conversation. */
export const MAIN = 'main';

type AgentBudget = {
	/** Nudges spent so far. */
	nudges: number;
	/** The turn in which the agent last called code_intel. */
	codeIntelTurn?: string;
};

/**
 * Per agent, what its budget has spent. Module state only: a reload of the
 * hooks module starts every budget over, which is acceptable.
 */
const budgets = new Map<string, AgentBudget>();

/**
 * The main conversation's current turn, from `turn.start`. A subagent's run is
 * one turn (its loop's `turn.complete` closes the run, and `forgetAgentBudget`
 * then drops its state), so its turn is its `agentId`.
 */
let mainTurn: string | undefined;

let nudgeLimit = DEFAULT_NUDGE_LIMIT;

/** The agent a tool call belongs to: `agentId` in a subagent, else the main conversation. */
export function agentKey(e: object): string {
	return stringArg(e, 'agentId') ?? MAIN;
}

function budgetOf(key: string): AgentBudget {
	let budget = budgets.get(key);
	if (budget === undefined) {
		budget = { nudges: 0 };
		budgets.set(key, budget);
	}
	return budget;
}

/** The turn the agent `key` is in, or undefined before the main conversation's first turn. */
function turnOf(key: string): string | undefined {
	return key === MAIN ? mainTurn : key;
}

/** True when the agent that made the tool call `e` already called code_intel in its current turn. */
export function usedCodeIntelThisTurn(e: object): boolean {
	const key = agentKey(e);
	const turn = turnOf(key);
	return turn !== undefined && budgets.get(key)?.codeIntelTurn === turn;
}

/** True when the agent that made `e` has a nudge left. Spends nothing. */
export function hasNudgeLeft(e: object): boolean {
	return (budgets.get(agentKey(e))?.nudges ?? 0) < nudgeLimit;
}

/** Spends one nudge from the budget of the agent that made `e`; false, spending nothing, once it is used up. */
export function spendNudge(e: object): boolean {
	const budget = budgetOf(agentKey(e));
	if (budget.nudges >= nudgeLimit) return false;
	budget.nudges += 1;
	return true;
}

export function registerBudget(on: On, options: PluginOptions): void {
	const limit = options.nudgeLimit;
	nudgeLimit = typeof limit === 'number' ? limit : DEFAULT_NUDGE_LIMIT;
	budgets.clear();
	mainTurn = undefined;

	on('turn.start', async (_$, e, next) => {
		mainTurn = e.turnId;
		return next(e);
	});

	on('tool.call', { tool: /code_intel$/ }, async ($, e, next) => {
		const key = agentKey(e);
		const turn = turnOf(key);
		if (turn !== undefined) budgetOf(key).codeIntelTurn = turn;
		const r = await next(e);
		// A plugin's own `$.mcp.call` of code_intel (this one's risk lookups among them) is not the agent's analysis,
		// and the onboarding and the freshness indicator act on its own pings themselves.
		if (next.origin.plugin === 'engine') {
			noteCodeIntel(key, e, r);
			try {
				observeCodeIntel(
					r,
					isConfigured(await $.env.get('CONSTELLATION_ACCESS_KEY')),
					() => $.ui.invalidate('ui.render'),
					async (text) => {
						if (!canDraw(await $.session.surfaces())) $.ui.log(text);
					},
				);
			} catch {
				// The band stays as it was; the agent's answer goes back untouched.
			}
			// A refused call never ran; an errored one is still the agent reaching for code_intel.
			if (r.deny === undefined) {
				const counted = noteCodeIntelCall(key === MAIN, parseToolText(r.text, r.isError === true).time);
				if (showsAdoption()) $.ui.invalidate('ui.render');
				// Saved in the background: the agent's answer never waits on the store.
				background(() =>
					save(counted, {
						now: () => $.clock.now(),
						sessionId: () => $.session.id(),
						get: (k) => $.store.get(k),
						set: (k, entry) => $.store.set(k, entry),
						keys: () => $.store.keys(),
						del: (k) => $.store.delete(k),
					}),
				);
				try {
					// The index the answer came from, for the project the call ran in. The answer does not wait for git.
					const session = await $.session.cwd();
					const cwd = stringArg(e, 'cwd');
					const root = await projectRoot(cwd === undefined ? session : absolute(cwd, session), (p) => $.fs.exists(p));
					if (root !== null) {
						void observeEnvelope(
							parseToolText(r.text, r.isError === true),
							root,
							(argv, init) => $.process.run(argv, init),
							() => $.ui.invalidate('ui.render'),
							async (text) => {
								if (!canDraw(await $.session.surfaces())) $.ui.log(text);
							},
						).catch(() => undefined);
					}
				} catch {
					// The indicator stays as it was.
				}
			}
		}
		return r;
	});
}

/** Starts every budget over, for a new conversation (`/clear`, `/resume`, `/branch`). */
export function resetBudgets(): void {
	budgets.clear();
}

/**
 * Drops the budget of the subagent `agentId` when its run ends. A subagent
 * continued later (SendMessage) keeps its id but starts a new run, so it gets a
 * fresh budget and its earlier code_intel call no longer counts as this turn's.
 */
export function forgetAgentBudget(agentId: string): void {
	budgets.delete(agentId);
}

