import type { ElementTable, On, PluginOptions, RenderElement, RenderNode } from 'claude-code';
import { isTestFile } from './blast';
import { explain } from './explain';
import { type CodeIntelEnvelope, isRecord, num, parseToolText, plural, projectName } from './lib';
import { badge, forTheme, kind, palette, risk, type Scheme, scheme, status, type Tone } from './theme';

/** The mark that opens a code_intel call row. */
const mark: Tone = { color: palette.nebula, word: 'code_intel', glyph: '✦' };

const SEP = ' · ';

/** Most rows remembered; the oldest is dropped past it. */
const MAX_ROWS = 200;

/** Symbol names a search row lists. */
const MAX_NAMES = 3;

/**
 * The project each call row named, by requestId (the tool_use_id), for its
 * result row: a result row has no input to read the `cwd` from.
 */
const projects = new Map<string, string>();

/** How long a settings read serves redraws: a resize redraws every row at once. */
const SETTINGS_MS = 1000;

/**
 * Claude Code's theme and verbose settings and when they were read. A
 * `config.set` drops them at once; `/theme` raises no event, so a read older
 * than SETTINGS_MS is read again.
 */
let settings: { theme: unknown; verbose: boolean; readAt: number } | undefined;

/** Forgets every row and the settings read, for a new conversation. */
export function resetToolRows(): void {
	projects.clear();
	settings = undefined;
}

function remember(id: string, project: string): void {
	projects.set(id, project);
	if (projects.size > MAX_ROWS) {
		const oldest = projects.keys().next().value;
		if (oldest !== undefined) projects.delete(oldest);
	}
}

/** The `api.*` methods `code` calls, each once, in order of first appearance. */
export function methodsOf(code: string): string[] {
	const names = [...code.matchAll(/\bapi\s*\??\.\s*(\w+)\s*\(/g)].map((m) => m[1]).filter((n): n is string => n !== undefined);
	return [...new Set(names)];
}

function firstText(blocks: unknown[]): string | undefined {
	for (const block of blocks) {
		if (isRecord(block) && block.type === 'text' && typeof block.text === 'string') return block.text;
	}
	return undefined;
}

/**
 * The text of a tool row's `output`: the string itself, else the first text
 * block of a content-block array or of an object's `content` array. Never
 * `structuredContent`: on an error it holds only a message, not the code or
 * guidance.
 */
export function outputText(output: unknown): string | undefined {
	if (typeof output === 'string') return output;
	if (Array.isArray(output)) return firstText(output);
	if (isRecord(output) && Array.isArray(output.content)) return firstText(output.content);
	return undefined;
}

function tinted(el: ElementTable, tone: Tone, text: string): RenderElement {
	return el.Text({
		...(tone.color === undefined ? {} : { color: tone.color }),
		...(tone.dimColor ? { dimColor: true } : {}),
		...(tone.bold ? { bold: true } : {}),
		children: text,
	});
}

/** `count` in bold and `word`, plural unless the count is one. */
function counted(el: ElementTable, count: number, word: string): RenderElement {
	const digits = String(count);
	return el.Text({ children: [el.Text({ bold: true, children: digits }), plural(count, word).slice(digits.length)] });
}

function dim(el: ElementTable, text: string): RenderElement {
	return el.Text({ dimColor: true, children: text });
}

/** The parts of a row with ` · ` between them. */
function joined(parts: RenderNode[]): RenderNode[] {
	return parts.flatMap((part, i) => (i === 0 ? [part] : [SEP, part]));
}

/** The children of a call row: the mark, the methods called, the project, and `running` until it ends. */
function callRow(el: ElementTable, methods: string[], project: string | undefined, running: boolean, to: Scheme): RenderNode[] {
	const parts: RenderNode[] = [badge(el, '', forTheme(mark, to))];
	if (methods.length > 0) parts.push(methods.join(', '));
	if (project) parts.push(dim(el, project));
	if (running) parts.push(dim(el, 'running'));
	return joined(parts);
}

function depthOf(nodes: unknown[]): number {
	return nodes.reduce<number>((max, n) => Math.max(max, (isRecord(n) ? num(n.depth) : undefined) ?? 0), 0);
}

/** The parts that describe `result`, by the distinctive keys of each method's result, else a generic count. */
function shape(el: ElementTable, result: unknown, to: Scheme, project: string | undefined): RenderNode[] {
	if (isRecord(result)) {
		const summary = isRecord(result.summary) ? result.summary : undefined;
		if (isRecord(result.breakingChangeRisk) || num(summary?.directDependentCount) !== undefined) {
			const parts: RenderNode[] = [];
			const level = isRecord(result.breakingChangeRisk) ? result.breakingChangeRisk.riskLevel : undefined;
			if (typeof level === 'string') parts.push(badge(el, '', forTheme(risk(level), to)));
			const direct = num(summary?.directDependentCount);
			if (direct !== undefined) parts.push(counted(el, direct + (num(summary?.transitiveDependentCount) ?? 0), 'dependent'));
			// ponytail: a zero test count is left out, since Core's impact analysis reports 0 even when tests depend on the symbol.
			const tests = num(summary?.testFileCount);
			if (tests !== undefined && tests > 0) parts.push(counted(el, tests, 'test file'));
			return parts;
		}
		if (Array.isArray(result.directDependents) && typeof result.file === 'string') {
			// The result is one page; the total is the server's. Test files are counted only when the page holds them all.
			const dependents = result.directDependents;
			const total = (isRecord(result.pagination) ? num(result.pagination.total) : undefined) ?? dependents.length;
			const parts: RenderNode[] = [counted(el, total, 'dependent file')];
			const tests = dependents.filter((d) => isRecord(d) && typeof d.filePath === 'string' && isTestFile(d.filePath)).length;
			if (tests > 0 && total === dependents.length) parts.push(counted(el, tests, 'test file'));
			return parts;
		}
		if (Array.isArray(result.directDependencies)) {
			const dependencies = result.directDependencies;
			const files = dependencies.filter((d) => isRecord(d) && d.type === 'file').length;
			const packages = dependencies.filter((d) => isRecord(d) && d.type === 'module').length;
			const parts: RenderNode[] = [counted(el, files, 'dependency file')];
			if (packages > 0) parts.push(counted(el, packages, 'package'));
			return parts;
		}
		if (Array.isArray(result.symbols)) {
			const symbols = result.symbols;
			const total = (isRecord(result.pagination) ? num(result.pagination.total) : undefined) ?? symbols.length;
			const parts: RenderNode[] = [counted(el, total, 'symbol')];
			const names = symbols
				.slice(0, MAX_NAMES)
				.filter((s): s is Record<string, unknown> => isRecord(s) && typeof s.name === 'string')
				.map((s) => tinted(el, forTheme(kind(typeof s.kind === 'string' ? s.kind : ''), to), String(s.name)));
			if (names.length > 0) parts.push(el.Text({ children: names.flatMap((n, i) => (i === 0 ? [n] : [', ', n])) }));
			return parts;
		}
		if (Array.isArray(result.orphanedSymbols)) {
			return [counted(el, num(summary?.totalOrphanedSymbols) ?? result.orphanedSymbols.length, 'export')];
		}
		if ('root' in result && (Array.isArray(result.callers) || Array.isArray(result.callees))) {
			const callers = Array.isArray(result.callers) ? result.callers : [];
			const callees = Array.isArray(result.callees) ? result.callees : [];
			const depth = Math.max(depthOf(callers), depthOf(callees));
			return [counted(el, callers.length + callees.length, 'node'), el.Text({ children: ['depth ', el.Text({ bold: true, children: String(depth) })] })];
		}
		if (result.pong === true) {
			const parts: RenderNode[] = [badge(el, '', forTheme({ ...status('success'), word: 'connected' }, to))];
			if (project) parts.push(dim(el, project));
			return parts;
		}
		return [el.Text({ children: ['result: ', counted(el, Object.keys(result).length, 'key')] })];
	}
	if (Array.isArray(result)) return [el.Text({ children: ['result: ', counted(el, result.length, 'item')] })];
	return [`result: ${typeof result}`];
}

/**
 * The children of a result row for `envelope`: an error's code as a badge, its
 * headline and the first step to take, or what the result holds and why it is
 * empty; then how long the call took and the commit the graph was indexed at.
 */
export function summarize(el: ElementTable, envelope: CodeIntelEnvelope, to: Scheme, project?: string): RenderNode[] {
	const { error } = envelope;
	const parts: RenderNode[] = [];
	if (!envelope.success && error !== undefined) {
		const ex = explain(error);
		parts.push(badge(el, '', forTheme({ ...status('error'), word: error.code }, to)), ex.title);
		if (ex.steps[0] !== undefined) parts.push(ex.steps[0]);
	} else {
		parts.push(...shape(el, envelope.result, to, project));
		if (envelope.reason !== undefined) parts.push(dim(el, envelope.reason.replace(/_/g, ' ')));
	}
	const meta: string[] = [];
	if (envelope.time !== undefined) meta.push(`${envelope.time} ms`);
	if (envelope.asOfCommit) meta.push(`as of ${envelope.asOfCommit.slice(0, 7)}`);
	if (meta.length > 0) parts.push(dim(el, meta.join(SEP)));
	return joined(parts);
}

/**
 * The code_intel call and result rows in the transcript: the call row reads
 * `✦ code_intel · <methods> · <project>` and the result row one line about what
 * came back. With the `verbose` setting on, Claude Code's own row follows
 * under it. Every other tool and surface, an interrupted call, and a result
 * with no envelope to read (one over the MCP output limit, say) or a failure
 * without an error code keeps Claude Code's own row.
 */
export function registerToolRows(on: On, options: PluginOptions): void {
	on('config.set', { key: ['theme', 'verbose'] }, async ($, e, next) => {
		const set = await next(e);
		settings = undefined;
		$.ui.invalidate('ui.render');
		return set;
	});

	on('ui.render', { component: ['ToolUse', 'ToolResult'] }, async ($, e, next) => {
		if (!/__code_intel$/.test(e.props.tool)) return next(e);
		if (e.surface !== 'terminal' && e.surface !== 'desktop') return next(e);
		if (e.component === 'ToolUse' && e.props.isInterrupted) return next(e);
		const el = $.ui.resolve(e);
		let row: RenderElement | undefined;
		let verbose = false;
		try {
			const now = await $.clock.now();
			if (settings === undefined || now - settings.readAt > SETTINGS_MS) {
				try {
					const config = await $.config.list();
					settings = {
						theme: config.find((r) => r.key === 'theme')?.value,
						verbose: config.find((r) => r.key === 'verbose')?.value === true,
						readAt: now,
					};
				} catch {
					// The default colors and Claude Code's row hidden, until a read succeeds.
				}
			}
			verbose = settings?.verbose ?? false;
			const to = scheme(options.colors, settings?.theme);
			if (e.component === 'ToolUse') {
				const input = e.props.input;
				if (isRecord(input) && typeof input.code === 'string') {
					const project = projectName(input.cwd);
					if (project !== undefined) remember(e.requestId, project);
					row = el.Text({ children: callRow(el, methodsOf(input.code), project, e.props.isRunning, to) });
				}
			} else {
				// An errored call's output is the text the model read.
				const envelope = parseToolText(outputText(e.props.output), e.props.isErrored);
				const drawable = envelope.error === undefined ? envelope.success && !e.props.isErrored : envelope.error.code !== 'INVALID_RESPONSE';
				if (drawable) row = el.Text({ children: summarize(el, envelope, to, projects.get(e.requestId)) });
			}
		} catch {
			row = undefined;
		}
		if (row === undefined) return next(e);
		if (!verbose) return row;
		return el.Box({ flexDirection: 'column', children: [row, await next(e)] });
	});
}

files.hooks/turnsummary.ts:
import type { On, PluginOptions } from 'claude-code';
import { type Blast, blastRadius } from './blast';
import { absolute, type McpPort, plural, projectRoot, relativeTo, stringArg, withinDeadline } from './lib';
import { PROMPT } from './theme';

/**
 * How long the end of a turn waits for the lookup before it shows no line. The
 * hook's own time limit pauses while `$.mcp.call` runs, so a slow server would
 * otherwise hold the answer for code_intel's full timeout.
 */
export const TURN_SUMMARY_DEADLINE_MS = 2000;

let enabled = true;

/** Absolute paths edited this turn, in the order they were first edited. */
const changed = new Set<string>();

/** Absolute paths a Write created this turn. */
const created = new Set<string>();

/** Drops the record of changed files: a new turn, a turn that ended with no answer, or a new conversation. */
export function resetTurnSummary(): void {
	changed.clear();
	created.clear();
}

/** What `summarizeTurn` needs from `$`, as closures the handler spells out. */
export type TurnSummaryPort = {
	exists: (path: string) => Promise<boolean>;
	mcp: McpPort;
	sleep: (ms: number, options: { signal: AbortSignal }) => Promise<unknown>;
};

/** The summary line for `n` changed files, `k` of them new, `queried` of them looked up, and their blast radius. */
function summaryLine(n: number, k: number, queried: number, blast: Blast): string {
	const fresh = k > 0 ? ` (${k} new)` : '';
	const tests = plural(blast.tests, 'test file');
	const commit = blast.asOfCommit === undefined ? '' : ` · as of ${blast.asOfCommit}`;
	const of = blast.skipped === undefined ? '' : ` of the first ${queried - blast.skipped} files`;
	const count = blast.atLimit === undefined ? plural(blast.dependents.length, 'downstream dependent') : `${blast.dependents.length}+ downstream dependents`;
	return `${PROMPT} ${plural(n, 'file')} changed${fresh} · ${count}${of} (${tests})${commit}`;
}

/**
 * One line on the files this turn changed in one project and how many files
 * depend on them, then a fresh record for the next turn. Files outside that
 * project (a plan, a scratch file, a sibling project) are left out of both. Undefined when the summary is off,
 * nothing changed, no changed file is in a Constellation project, or
 * the lookup failed or missed `TURN_SUMMARY_DEADLINE_MS`.
 */
export async function summarizeTurn(port: TurnSummaryPort, signal: AbortSignal): Promise<string | undefined> {
	if (!enabled || changed.size === 0) return undefined;
	const files = [...changed];
	const fresh = new Set(created);
	resetTurnSummary();
	// The first changed file inside a project picks the root, so a plan or scratch file edited first does not hide the line.
	let root: string | null = null;
	for (const path of files) {
		root = await projectRoot(absolute('..', path), port.exists);
		if (root !== null) break;
	}
	if (root === null) return undefined;
	const inside = root;
	const inProject = files.filter((path) => relativeTo(inside, path) !== null);
	const added = inProject.filter((path) => fresh.has(path)).length;
	const queried = inProject.flatMap((path) => {
		const rel = fresh.has(path) ? null : relativeTo(inside, path);
		return rel === null ? [] : [rel];
	});
	const blast: Blast | undefined =
		queried.length === 0
			? { dependents: [], tests: 0, exports: [] }
			: await withinDeadline(port.sleep, blastRadius(port.mcp, root, queried, { exports: false }), TURN_SUMMARY_DEADLINE_MS, signal);
	return blast === undefined ? undefined : summaryLine(inProject.length, added, queried.length, blast);
}

export function registerTurnSummary(on: On, options: PluginOptions): void {
	enabled = options.turnSummary !== false;
	resetTurnSummary();
	if (!enabled) return;

	// Every agent's edits count, a subagent's included: the line sums up what the turn changed.
	on('tool.call', { tool: /^(Edit|Write|MultiEdit|NotebookEdit)$/ }, async ($, e, next) => {
		const raw = stringArg(e, 'file_path') ?? stringArg(e, 'notebook_path');
		if (raw === undefined) return next(e);
		const path = absolute(raw, await $.session.cwd());
		const creates = String(e.tool) === 'Write' && !(await $.fs.exists(path));
		const r = await next(e);
		if (r.deny === undefined && !r.isError) {
			changed.add(path);
			if (creates) created.add(path);
		}
		return r;
	});
}

files.hooks/lib.ts:
import type { EngineInterface, RenderSurface } from 'claude-code';

/**
 * The MCP calls `codeIntel` makes. `claude plugin validate` follows `$` only
 * into functions declared in the same file, so a handler passes closures that
 * spell `$.mcp.connect(...)` and `$.mcp.call(...)` itself:
 * `{ connect: (s) => $.mcp.connect(s), call: (s, t, a) => $.mcp.call(s, t, a) }`.
 */
export type McpPort = Pick<EngineInterface['mcp'], 'connect' | 'call'>;

export type CodeIntelError = {
	code: string;
	message?: string;
	guidance?: readonly string[];
	/** Project roots code_intel found under the git root, sent with `CWD_NOT_INDEXED`. */
	candidates?: readonly string[];
	/** A documentation link the server sends with the error. */
	docs?: string;
};

export type CodeIntelEnvelope = {
	success: boolean;
	result?: unknown;
	error?: CodeIntelError;
	asOfCommit?: string;
	lastIndexedAt?: string;
	time?: number;
	/** Why a result came back empty (`resultContext.reason`), such as `branch_not_indexed`. */
	reason?: string;
};

/** How long each git command may run. */
export const GIT_TIMEOUT_MS = 5000;

/**
 * git with the repository's fsmonitor, hooks and network transports turned
 * off, since the command runs before Claude Code asks about the Bash call it
 * guards. The diff skips rename detection, which is what would fetch missing
 * objects in a partial clone, and `GIT_NO_LAZY_FETCH` stops any other fetch.
 */
export const GIT = ['git', '-c', 'core.fsmonitor=false', '-c', 'core.hooksPath=/dev/null', '-c', 'protocol.allow=never'];
export const GIT_ENV = { GIT_NO_LAZY_FETCH: '1' };

const SERVER_KEY = 'constellation';
const PROJECT_FILE = 'constellation.json';

/**
 * True when the access key starts with `ak:`, the same gate the settings hooks
 * used. The handler reads it, so validate sees the literal name:
 * `isConfigured(await $.env.get('CONSTELLATION_ACCESS_KEY'))`.
 */
export function isConfigured(accessKey: string | undefined): boolean {
	return (accessKey ?? '').startsWith('ak:');
}

/**
 * True when the session can draw a pane: a `terminal` or `desktop` surface is
 * present. `CommandRunInput` has no surface field, so the handler passes
 * `await $.session.surfaces()`, which validate sees as a literal call. Later
 * pane stories reuse this check.
 */
export function canDraw(surfaces: readonly RenderSurface[]): boolean {
	return surfaces.includes('terminal') || surfaces.includes('desktop');
}

/** The string field `name` of a tool call or event, or undefined. */
export function stringArg(e: object, name: string): string | undefined {
	const value: unknown = Reflect.get(e, name);
	return typeof value === 'string' ? value : undefined;
}

/** Resolves `path` against `cwd` into an absolute, forward-slash path with no `.` or `..` segments. */
export function absolute(path: string, cwd: string): string {
	const full = path.replace(/\\/g, '/');
	const joined = /^([A-Za-z]:)?\//.test(full) ? full : `${cwd.replace(/\\/g, '/')}/${full}`;
	const root = /^([A-Za-z]:)?\//.exec(joined)?.[0] ?? '/';
	const segments: string[] = [];
	for (const segment of joined.slice(root.length).split('/')) {
		if (segment === '..') segments.pop();
		else if (segment !== '' && segment !== '.') segments.push(segment);
	}
	return root + segments.join('/');
}

/** `path` (absolute, normalized) relative to `root` in POSIX form, or null when it is outside the root. */
export function relativeTo(root: string, path: string): string | null {
	const base = absolute(root, root).replace(/\/+$/, '');
	return path.startsWith(`${base}/`) ? path.slice(base.length + 1) : null;
}

/** `value` when it is an array of strings, else undefined. */
export function strings(value: unknown): string[] | undefined {
	return Array.isArray(value) && value.every((v) => typeof v === 'string') ? (value as string[]) : undefined;
}

/** `count` and `word`, with an `s` unless the count is one. */
export function plural(count: number, word: string): string {
	return `${count} ${word}${count === 1 ? '' : 's'}`;
}

/**
 * The nearest directory at or above `path` (default: `cwd`) that holds an
 * entry called `name`, or null. Walks up with `exists` (`(p) => $.fs.exists(p)`)
 * because `$.fs.ancestors` only accepts `.md` file names.
 */
async function findUp(
	cwd: string,
	exists: (path: string) => Promise<boolean>,
	name: string,
	path?: string,
): Promise<string | null> {
	let dir = absolute(path ?? cwd, cwd);
	for (;;) {
		const prefix = dir.endsWith('/') ? dir : `${dir}/`;
		if (await exists(prefix + name)) return dir;
		const parent = absolute('..', dir);
		if (parent === dir) return null;
		dir = parent;
	}
}

/**
 * The nearest directory at or above `path` (default: `cwd`) that holds a
 * `constellation.json`, or null. `path` may be a file or a directory; a
 * relative one is resolved against `cwd`.
 */
export function projectRoot(cwd: string, exists: (path: string) => Promise<boolean>, path?: string): Promise<string | null> {
	return findUp(cwd, exists, PROJECT_FILE, path);
}

/**
 * The nearest directory at or above `cwd` that holds `.git`, or null outside a
 * git repository. `$.fs.exists` answers for any entry, so a `.git` directory
 * and a worktree's `.git` file both count. No git process runs.
 */
export function gitRoot(cwd: string, exists: (path: string) => Promise<boolean>): Promise<string | null> {
	return findUp(cwd, exists, '.git');
}

function failure(code: string, message: string): CodeIntelEnvelope {
	return { success: false, error: { code, message } };
}

export function isRecord(value: unknown): value is Record<string, unknown> {
	return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** `value` when it is a finite number, else undefined. */
export function num(value: unknown): number | undefined {
	return typeof value === 'number' && Number.isFinite(value) ? value : undefined;
}

/** The last segment of a string path, split on either slash, as a project's name. */
export function projectName(path: unknown): string | undefined {
	return typeof path === 'string' ? path.split(/[\\/]/).filter(Boolean).pop() : undefined;
}

function parseError(value: unknown): CodeIntelError | undefined {
	if (!isRecord(value) || typeof value.code !== 'string') return undefined;
	const error: CodeIntelError = { code: value.code };
	if (typeof value.message === 'string') error.message = value.message;
	if (Array.isArray(value.guidance)) {
		error.guidance = value.guidance.filter((g): g is string => typeof g === 'string');
	}
	if (typeof value.docs === 'string' && value.docs !== '') error.docs = value.docs;
	const candidates = isRecord(value.context) ? value.context.candidates : undefined;
	if (Array.isArray(candidates)) {
		error.candidates = candidates.filter((c): c is string => typeof c === 'string');
	}
	return error;
}

/** Reads a code_intel response body into the typed envelope, or a stable parse failure. */
export function parseEnvelope(text: string | undefined): CodeIntelEnvelope {
	if (text === undefined) return failure('INVALID_RESPONSE', 'code_intel returned no text content');
	let body: unknown;
	try {
		body = JSON.parse(text);
	} catch {
		return failure('INVALID_RESPONSE', 'code_intel returned text that is not JSON');
	}
	if (!isRecord(body) || typeof body.success !== 'boolean') {
		return failure('INVALID_RESPONSE', 'code_intel returned JSON without a success flag');
	}
	const envelope: CodeIntelEnvelope = { success: body.success };
	if ('result' in body) envelope.result = body.result;
	const error = parseError(body.error);
	if (error) envelope.error = error;
	if (typeof body.asOfCommit === 'string') envelope.asOfCommit = body.asOfCommit;
	if (typeof body.lastIndexedAt === 'string') envelope.lastIndexedAt = body.lastIndexedAt;
	if (typeof body.time === 'number') envelope.time = body.time;
	const reason = isRecord(body.resultContext) ? body.resultContext.reason : undefined;
	if (typeof reason === 'string' && reason !== '') envelope.reason = reason;
	return envelope;
}

/**
 * Reads the text a code_intel call gave the model into the envelope. An
 * errored call's text is `Error: ` and then the envelope, so the prefix goes first.
 */
export function parseToolText(text: string | undefined, isError: boolean): CodeIntelEnvelope {
	return parseEnvelope(isError ? text?.replace(/^Error:\s*/, '') : text);
}

/**
 * Runs `code` through the plugin's `code_intel` MCP tool in the project at `cwd`.
 * Connects on every call: `$.mcp.connect` answers at once for a connected
 * server and gives the name it runs under now, so a restarted or renamed server
 * is picked up without a cache to go stale. Never throws: every failure is an
 * envelope with `success: false`.
 */
export async function codeIntel(mcp: McpPort, code: string, { cwd }: { cwd: string }): Promise<CodeIntelEnvelope> {
	try {
		const connection = await mcp.connect(SERVER_KEY);
		if (!connection.isConnected) {
			return failure('MCP_UNAVAILABLE', `${connection.reason}: ${connection.message}`);
		}
		const response = await mcp.call(connection.server, 'code_intel', { code, cwd });
		const text = response.content.find((block) => block.type === 'text')?.text;
		const envelope = parseEnvelope(text);
		if (!response.isError) return envelope;
		// An error result may still carry code_intel's own envelope (an error code
		// and guidance); anything else, such as a host message, is MCP_TOOL_ERROR.
		if (envelope.error !== undefined && envelope.error.code !== 'INVALID_RESPONSE') return { ...envelope, success: false };
		return failure('MCP_TOOL_ERROR', text ?? 'code_intel returned an error');
	} catch (error) {
		return failure('MCP_CALL_FAILED', error instanceof Error ? error.message : String(error));
	}
}

/**
 * `pending` if it settles within `ms` (and before `signal` aborts), else
 * undefined. `sleep` is `(ms, o) => $.clock.sleep(ms, o)`: the hook's own time
 * limit pauses during `$` calls, so a slow lookup needs a deadline of its own.
 */
export async function withinDeadline<T>(
	sleep: (ms: number, options: { signal: AbortSignal }) => Promise<unknown>,
	pending: Promise<T>,
	ms: number,
	signal: AbortSignal,
): Promise<T | undefined> {
	const stop = new AbortController();
	const deadline = sleep(ms, { signal: AbortSignal.any([signal, stop.signal]) }).then(
		() => undefined,
		() => undefined,
	);
	try {
		return await Promise.race([pending, deadline]);
	} finally {
		stop.abort();
	}
}

