import { isRecord, num } from './lib';

/** One unused export as the pane lists it and the removal prompt names it. */
export type OrphanRow = {
	symbolId: string;
	name: string;
	kind: string;
	filePath: string;
	/** The graph holds no start line, only the end line, and not for every symbol. */
	lineEnd?: number;
};

function str(value: unknown): string | undefined {
	return typeof value === 'string' && value !== '' ? value : undefined;
}

/**
 * Runs inside code_intel: `orphanCode` sends its source, so it may use only
 * its arguments. It returns only the fields the pane reads: each row's source
 * snippet would make a page of a large project too big for Claude Code's MCP
 * output limit, which then hands back a note instead of the JSON.
 */
export async function orphanQuery(
	api: { findOrphanedCode: (params: object) => Promise<{ orphanedSymbols?: unknown; summary?: unknown; pagination?: unknown }> },
	params: object,
) {
	const found = await api.findOrphanedCode(params);
	const rows: ReadonlyArray<Record<string, unknown>> = Array.isArray(found.orphanedSymbols) ? found.orphanedSymbols : [];
	return {
		orphanedSymbols: rows.map((s) => ({ symbolId: s.symbolId, name: s.name, kind: s.kind, filePath: s.filePath, lineEnd: s.lineEnd })),
		summary: found.summary,
		pagination: found.pagination,
	};
}

/** The code one page of unused exports sends, with the kind filter and paging in `params`. */
export function orphanCode(params: object): string {
	return `return await (${orphanQuery.toString()})(api, ${JSON.stringify(params)});`;
}

/**
 * One page of a `findOrphanedCode` result: its rows, the total the graph
 * reports, and the offset of the next page when there is one. The result is
 * untyped, so every field is narrowed before it is read.
 */
export function orphanPage(result: unknown): { rows: OrphanRow[]; total?: number; nextOffset?: number } {
	if (!isRecord(result)) return { rows: [] };
	const rows: OrphanRow[] = [];
	if (Array.isArray(result['orphanedSymbols'])) {
		for (const entry of result['orphanedSymbols']) {
			if (!isRecord(entry)) continue;
			const symbolId = str(entry['symbolId']);
			const name = str(entry['name']);
			const filePath = str(entry['filePath']);
			if (symbolId === undefined || name === undefined || filePath === undefined) continue;
			const lineEnd = num(entry['lineEnd']);
			rows.push({ symbolId, name, kind: str(entry['kind']) ?? 'unknown', filePath, ...(lineEnd === undefined ? {} : { lineEnd }) });
		}
	}
	const page: { rows: OrphanRow[]; total?: number; nextOffset?: number } = { rows };
	const total = isRecord(result['summary']) ? num(result['summary']['totalOrphanedSymbols']) : undefined;
	if (total !== undefined) page.total = total;
	const pagination = result['pagination'];
	if (isRecord(pagination) && pagination['hasMore'] === true) {
		const next = num(pagination['nextOffset']);
		if (next !== undefined) page.nextOffset = next;
	}
	return page;
}

/** The rows grouped by file, files in the order they first appear. */
export function byFile(rows: readonly OrphanRow[]): Map<string, OrphanRow[]> {
	const files = new Map<string, OrphanRow[]>();
	for (const row of rows) {
		const group = files.get(row.filePath);
		if (group === undefined) files.set(row.filePath, [row]);
		else group.push(row);
	}
	return files;
}

/** The file, and its end line when the graph has one. */
export function location(row: OrphanRow): string {
	return row.lineEnd === undefined ? row.filePath : `${row.filePath}:${row.lineEnd}`;
}

/**
 * The prompt that hands the picked exports to the model. It asks for a check
 * before any deletion, because the graph can list a symbol as unused when it
 * is only imported through a path alias or an `export *` barrel.
 */
export function removalPrompt(rows: readonly OrphanRow[], commit?: string): string {
	const lines = [
		'Remove these unused exports. For each one, confirm it is unused with code_intel (traceSymbolUsage and impactAnalysis) and a literal text search for string references (reflection, DI tokens, config, framework entry points) before deleting it; skip any that are still referenced. Constellation can report symbols as unused when they are imported through tsconfig path aliases or export * barrels, so do not skip the check.',
	];
	if (commit !== undefined && commit !== '') lines.push(`Graph as of ${commit.slice(0, 7)}.`);
	for (const row of rows) lines.push(`- \`${row.name}\` (${row.kind}) in ${location(row)}`);
	return lines.join('\n');
}

files.hooks/blast.ts:
import { codeIntel, type McpPort, strings } from './lib';

export type Blast = {
	/** Project-relative files that depend on the inspected files, minus every inspected file, those importing the most of them first. */
	dependents: string[];
	/** How many of the dependents are test files. */
	tests: number;
	/** The inspected files' symbols the dependents import; empty unless asked for. */
	exports: string[];
	/** The first 7 characters of the commit the graph was indexed at. */
	asOfCommit?: string;
	/** How many files past the cap were not looked up; absent when all were. */
	skipped?: number;
	/** True when a file filled its page of dependents, so the count is a floor. */
	atLimit?: true;
};

/**
 * Most files one lookup inspects. code_intel allows 50 `api.*` calls per run
 * and the probe makes one per file.
 */
const MAX_FILES = 50;

/** Most dependents read per file. */
const PAGE = 100;

/**
 * True for test files: `*.test.*`, `*.spec.*`, a `__tests__`, `test` or `tests`
 * directory (any case) or a `.Tests` project, Go `_test.go`, Python `test_*.py`
 * and `*_test.py`, C# and Java `*Test` and `*Tests` classes.
 */
export function isTestFile(path: string): boolean {
	const p = path.replace(/\\/g, '/');
	const name = p.slice(p.lastIndexOf('/') + 1);
	return (
		/\.(?:test|spec)\./.test(name) ||
		/(?:^|\/)(?:__tests__|[Tt]ests?|[^/]+\.Tests?)\//.test(p) ||
		name.endsWith('_test.go') ||
		/^test_.*\.py$/.test(name) ||
		/_test\.py$/.test(name) ||
		/[a-z0-9]Tests?\.(?:cs|java|kt)$/.test(name)
	);
}

/**
 * Runs inside code_intel: `blastRadius` sends its source, so it may use only
 * its arguments. One `getDependents` per file, with the symbols each dependent
 * imports. A file the graph does not know (new, or not indexed) has no
 * dependents; any other failure (auth, the server, the call cap) fails the
 * whole lookup rather than reading as zero.
 */
export async function probe(
	api: {
		getDependents: (p: { filePath: string; limit: number; includeSymbols: boolean }) => Promise<{
			directDependents: ReadonlyArray<{ filePath: string; usedSymbols?: readonly string[] }>;
		}>;
	},
	files: string[],
	withSymbols: boolean,
	page: number,
) {
	const perFile = await Promise.all(
		files.map(async (filePath) => {
			try {
				const found = await api.getDependents({ filePath, limit: page, includeSymbols: withSymbols });
				return found.directDependents;
			} catch (error) {
				if (/File not found/.test(error instanceof Error ? error.message : String(error))) return [];
				throw error;
			}
		}),
	);
	return {
		dependents: perFile.flat().map((d) => ({ filePath: d.filePath, symbols: [...(d.usedSymbols ?? [])] })),
		atLimit: perFile.some((d) => d.length >= page),
	};
}

/**
 * Who depends on `files` (project-relative, inside `root`) in the code graph,
 * and with `exports` which of their symbols those dependents import.
 * Undefined when the lookup failed. Never throws.
 */
export async function blastRadius(
	mcp: McpPort,
	root: string,
	files: string[],
	{ exports }: { exports: boolean },
): Promise<Blast | undefined> {
	try {
		const sent = files.slice(0, MAX_FILES);
		const code = `return await (${probe.toString()})(api, ${JSON.stringify(sent)}, ${JSON.stringify(exports)}, ${PAGE});`;
		const envelope = await codeIntel(mcp, code, { cwd: root });
		const result: unknown = envelope.result;
		const body = typeof result === 'object' && result !== null ? (result as Record<string, unknown>) : undefined;
		const edges = Array.isArray(body?.dependents) ? (body.dependents as unknown[]) : undefined;
		if (!envelope.success || edges === undefined) return undefined;
		// Every changed file is excluded, past the cap too: it is a changed file, not a dependent.
		const changed = new Set(files);
		const hits = new Map<string, number>();
		const used = new Set<string>();
		for (const edge of edges) {
			const filePath: unknown = typeof edge === 'object' && edge !== null ? Reflect.get(edge, 'filePath') : undefined;
			const symbols = strings(typeof edge === 'object' && edge !== null ? Reflect.get(edge, 'symbols') : undefined);
			if (typeof filePath !== 'string' || symbols === undefined) return undefined;
			if (changed.has(filePath)) continue;
			hits.set(filePath, (hits.get(filePath) ?? 0) + 1);
			for (const symbol of symbols) used.add(symbol);
		}
		const dependents = [...hits.keys()].sort((a, b) => (hits.get(b) ?? 0) - (hits.get(a) ?? 0) || (a < b ? -1 : a > b ? 1 : 0));
		const blast: Blast = { dependents, tests: dependents.filter(isTestFile).length, exports: [...used] };
		const commit = envelope.asOfCommit?.slice(0, 7);
		if (commit !== undefined) blast.asOfCommit = commit;
		if (files.length > sent.length) blast.skipped = files.length - sent.length;
		if (body?.atLimit === true) blast.atLimit = true;
		return blast;
	} catch {
		return undefined;
	}
}

